  settings.read(corrupt);
  close(settings.worldScale,1,"NaN scale rejected"); close(settings.renderScale,1,"infinite render scale rejected");
  test(settings.smoothSpeed==180,"smooth speed upper bound"); test(settings.snapAngle==15,"snap angle lower bound");
  test(settings.turn==Vr::TurnMode::Snap,"invalid turn mode"); close(settings.hudDistance,1,"HUD distance lower bound");
  settings.worldScale=1.35f; settings.renderScale=0.75f; settings.turn=Vr::TurnMode::Smooth; settings.roomScale=false;
  std::ostringstream saved; settings.write(saved); Vr::Settings restored; std::istringstream input(saved.str()); restored.read(input);
  close(restored.worldScale,1.35f,"world scale round trip"); close(restored.renderScale,0.75f,"render scale round trip");
  test(restored.turn==Vr::TurnMode::Smooth && !restored.roomScale,"mode round trip");
