  auto step=[&] { now+=20; return menu.update(in,now); };
  auto release=[&] { in={}; in.focused=true; step(); };
  test(step(),"first neutral input is consumed"); test(!step(),"gameplay after neutral");
  in.leftGrip=in.rightGrip=in.menu=true;
  test(step()&&menu.visible,"chord opens VR menu and consumes input");
  test(step()&&menu.visible,"held chord cannot retoggle"); release();
  test(menu.rows().size()==11 && menu.row()==Vr::Menu::Locomotion,"main menu exposes submenus");
  in.a=true; step(); test(menu.page==Vr::Menu::Page::Locomotion&&!menu.changed,"A enters locomotion without changing settings");
  step(); test(menu.settings.turn==Vr::TurnMode::Snap,"held A on entry cannot change turn mode"); release();
  in.a=true; step(); test(menu.settings.turn==Vr::TurnMode::Smooth && menu.changed,"A changes selected setting");
  step(); test(!menu.changed,"held A cannot repeat setting change"); release();
  in.y=1; step(); test(menu.selected==1,"stick selects next row");
  step(); test(menu.selected==1,"repeat delayed"); now+=420; step(); test(menu.selected==2,"held navigation repeats"); release();
  in.b=true; step(); test(menu.page==Vr::Menu::Page::Main&&menu.visible,"B returns from submenu without closing VR menu");
  step(); test(menu.visible,"held B cannot close parent"); release();
  in.y=1; step(); release(); in.a=true; step();
  test(menu.page==Vr::Menu::Page::Hud,"HUD submenu reachable with controls"); release();
  menu.selected=4; in.x=1; step(); close(menu.settings.hudX,0.025f,"HUD shifts right in 2.5 percent steps");
  test(menu.changed&&!menu.recenter,"HUD offset saves without recentering world"); release();
  in.y=1; step(); release(); in.x=-1; step(); close(menu.settings.hudY,-0.025f,"HUD vertical adjustment"); release();
  in.y=1; step(); release(); in.a=true; step(); close(menu.settings.hudX,0,"HUD reset horizontal"); close(menu.settings.hudY,0,"HUD reset vertical"); release();
  in.b=true; step(); release(); in.b=true; step(); test(!menu.visible,"B closes root menu");
