  release(); in.leftGrip=in.rightGrip=in.menu=true; step(); test(menu.visible,"released chord works after focus gain"); release();
  in.a=true; step(); release(); menu.selected=3; in.x=1; step();
  test(menu.changed&&menu.recenter,"scale change requests recenter"); close(menu.settings.worldScale,1.05f,"scale step"); release();
  in.b=true; step(); release(); menu.selected=2; in.a=true; step(); release();
  test(menu.page==Vr::Menu::Page::Performance,"performance submenu reachable"); menu.selected=1; in.a=true; step(); test(menu.settings.fogMode==1,"fog comparison mode changes"); release();
  menu.selected=3; in.a=true; step(); test(menu.settings.gpuSampling==2,"every-frame GPU measurement selectable");
