  test(horizonRestored.horizon==0 && !horizonRestored.directOutput && horizonRestored.horizonHaze,"Horizon persists with existing preferences");
  std::istringstream invalidHorizon("Horizon=9\n"); horizonRestored.read(invalidHorizon); test(horizonRestored.horizon==3,"out-of-range horizon clamps to 1 km");
