  release(); in.x=-1; step();
  test(menu.settings.cpuLevel==3 && menu.settings.gpuLevel==4 && menu.changed && !menu.recenter,"CPU level steps from Boost to Sustained high independently");
  step(); test(menu.settings.cpuLevel==3 && !menu.changed,"held stick cannot repeat CPU level step"); release();
  in.x=1; step(); release(); in.x=1; step(); release(); test(menu.settings.cpuLevel==0,"CPU level wraps to Runtime default");
  in.x=-1; step(); release(); test(menu.settings.cpuLevel==4,"CPU level wraps back to Boost");
  in.y=1; step(); release(); in.x=-1; step(); release();
  test(menu.row()==Vr::Menu::GpuLevel && menu.settings.gpuLevel==3 && menu.settings.cpuLevel==4,"GPU level steps independently of CPU");
  in.x=-1; step(); release(); in.x=-1; step(); release(); test(menu.settings.gpuLevel==1,"GPU level reaches Power savings");
  std::ostringstream powerIni; menu.settings.write(powerIni); Vr::Settings powerRestored; std::istringstream powerInput(powerIni.str()); powerRestored.read(powerInput);
  test(powerRestored.cpuLevel==4 && powerRestored.gpuLevel==1 && powerRestored.horizon==1,"CPU and GPU levels persist with the horizon");
