  in.x=1; step(); test(menu.settings.localLights && !menu.settings.lighting && !menu.settings.shadows,"local lights preference can remain on in unlit mode"); release();
  menu.selected=3; in.a=true; step(); test(!menu.settings.frameOverlap && menu.changed,"CPU/GPU overlap comparison toggles independently"); release();
  std::ostringstream overlapIni; menu.settings.write(overlapIni); Vr::Settings overlapRestored; std::istringstream overlapInput(overlapIni.str()); overlapRestored.read(overlapInput);
  test(!overlapRestored.frameOverlap,"CPU/GPU overlap preference persists");
