  close(motion.delta({0.2f,0,0},false).length(),0,"VR menu pauses body motion");
  close(motion.correction({0.2f,0,0},100).x,20,"opening VR menu cannot shift camera after room walk");
  close(motion.correction({0.25f,0,0},100).x,20,"head translation still tracked while VR menu open");
  close(motion.delta({0.25f,0,0},true).x,0.05f,"resume reconciles physical menu movement");
  motion.consume({0.05f,0,0});
  motion.delta({0.45f,0,0},true); motion.consume({0.05f,0,0});
